"""One-command release build: rebuild strategy results from data on disk, write a manifest, generate RESULTS.md
Usage: python3 scripts/build_release.py [--skip-strategies]"""
import sys, json, subprocess, hashlib, datetime as dt, numpy as np, pandas as pd
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent)); import edge_lib as E
OUT=E.RESULTS/'release'; OUT.mkdir(exist_ok=True,parents=True)
if '--skip-strategies' not in sys.argv:
    for s in ['release_weather.py','release_xvenue.py']:
        print('running',s,flush=True); r=subprocess.run([sys.executable,str(E.ROOT/'scripts'/s)],capture_output=True,text=True)
        (OUT/f'{s}.log').write_text(r.stdout+'\n'+r.stderr)
        if r.returncode!=0: print(r.stderr[-3000:]); raise SystemExit(f'{s} failed')
W=json.load(open(OUT/'weather.json')); Xv=json.load(open(OUT/'xvenue.json'))
# ---------------- manifest: every input consumed, with hashes
inputs=[E.DATA/'weather/candles_ev.parquet',E.DATA/'weather/fcst_daily.parquet',E.DATA/'weather/cli_daily.parquet',E.DATA/'weather/events.parquet',E.DATA/'kalshi/brackets.parquet',E.DATA/'kalshi/exclusions.parquet',
        E.DATA/'kalshi/xvenue_panel.parquet',E.DATA/'kalshi/xvenue_panel_poly.parquet',E.DATA/'kalshi/xvenue_poly_scored.parquet',E.DATA/'kalshi/candles_long.parquet',E.DATA/'kalshi/poly_prices',E.DATA/'kalshi/candles']
def rng(p,col):
    try: d=pd.read_parquet(p,columns=[col]); d=pd.to_datetime(d[col].astype(str)); return dict(rows=int(len(d)),first=str(d.min().date()),last=str(d.max().date()))
    except Exception as e: return {}
man=dict(built_utc=dt.datetime.now(dt.timezone.utc).isoformat(),env=E.env_info(),inputs=E.file_manifest(inputs),
         ranges={'candles_ev':rng(E.DATA/'weather/candles_ev.parquet','target'),'fcst_daily':rng(E.DATA/'weather/fcst_daily.parquet','date'),'cli_daily':rng(E.DATA/'weather/cli_daily.parquet','date'),'xvenue_poly_scored':rng(E.DATA/'kalshi/xvenue_poly_scored.parquet','target')},
         sources={'kalshi':'https://api.elections.kalshi.com/trade-api/v2 (historical markets, candlesticks)','polymarket':'gamma-api.polymarket.com events + clob.polymarket.com prices-history (midpoint, fidelity 60)','forecasts':'Open-Meteo previous-runs archive (previous_day1..3) and single-run API','truth':'NWS CLI via Iowa Environmental Mesonet; ASOS daily where no CLI'},
         commands=['zsh scripts/rebuild.sh','python3 scripts/xvenue_build.py && python3 scripts/xvenue_poly2.py','python3 scripts/build_release.py'],
         code_sha256={p.name:E.sha256(p) for p in sorted((E.ROOT/'scripts').glob('*.py'))})
json.dump(man,open(OUT/'manifest.json','w'),indent=1)
# frozen trades hash for the regression test
t=pd.read_parquet(OUT/'weather_trades.parquet'); h=pd.util.hash_pandas_object(t[['ticker','side','pnl']].round(6).reset_index(drop=True),index=False).sum()
(OUT/'frozen_trades_sha256.txt').write_text(f'{int(h)} weather_trades.parquet {len(t)} rows\n')
# ---------------- RESULTS.md (auto-generated; the only place numbers should be quoted from)
def c(x,d=1): return f'{x*100:+.{d}f}c'
w=W['modes']['ols']['h8']; wr=W['modes']['ridge']['h8']; p=w['primary']; pr=wr['primary']
x1=Xv['trading']['lp+lx|ALL']; xd=Xv['trading']['lp+lx|DEV']; xh=Xv['trading']['lp+lx|HOLDOUT']; xf=Xv['trading']['lp+lx|HOLDOUT|frozen_coefficients_fit_through_2026-03']; xb=Xv['trading']['lp+lx+lpm|HOLDOUT']
vi=Xv.get('vecm_information_share',{}); ic=Xv['identical_contracts']
def row(lab,s): return f"| {lab} | {s['N']:,} | {c(s['pnl_ct'])} | {s['t_event']} | {s['t_day']} | {s['ci95_pnl_ct_event'][0]*100:+.1f} to {s['ci95_pnl_ct_event'][1]*100:+.1f}c | {s['win']*100:.0f}% | {s['roi']*100:+.1f}% | {s['sharpe_capital']} | ${s['capital']:,.0f} | {s['sharpe_1lot_pnl']} |"
hdr='| Sample | N | per contract | t (event-clustered) | t (day-clustered) | 95% CI (event) | win | ROI | Sharpe on capital | capital | 1-lot P&L Sharpe (diagnostic) |\n|---|---|---|---|---|---|---|---|---|---|---|'
md=f"""# RESULTS (auto-generated by scripts/build_release.py on {man['built_utc'][:16]}Z; do not edit by hand)

All figures are historical simulations. Execution is modelled (quoted candle ask/bid on Kalshi with the taker fee; Polymarket midpoint plus an assumed half-spread), not demonstrated fills. "Sharpe on capital" divides daily P&L by a fixed capital equal to the maximum daily gross cost over the window (so every day fits inside it) and includes every calendar day in the evaluation window (zero when inactive). The 1-lot P&L Sharpe is the older diagnostic and is not a return-on-capital statistic.

## Strategy 1: forecast blend vs Kalshi daily-high brackets (decision time D-1 22:00Z, threshold 5c, taker fee)
Evaluation window {W['spec']['start']} to {man['ranges']['candles_ev'].get('last')}; {p['events']:,} scored events over {p['days_active']:,} active days; 18 stations. Blend weights from years before the target year; logistic combination refit monthly on all prior months (expanding window, 120-event warm-up). Decision time is clock-based: {w['decision_utc_hour_share']} share of decision timestamps by UTC hour; {w['decision_on_D_minus_1_share']*100:.1f}% of decisions fall on D-1.

**Timing caveat (open, P0):** {W['spec']['timing_caveat']}

{hdr}
{row('All-year, OLS blend (primary)',p)}
{row('All-year, ridge blend (regularised; alpha by 5-fold CV inside the training window)',pr)}
{row('Nov-Mar trades only, Sharpe over all calendar days',w['season_winter_as_strategy_all_days'])}
{row('Jun-Sep trades only, Sharpe over all calendar days',w['season_summer_as_strategy_all_days'])}
{row('Apr/May/Oct trades only, Sharpe over all calendar days',w['season_shoulder_as_strategy_all_days'])}
{row('Equal weight per bracket in the logistic (GLM)',w['primary_equal_event_weight'])}
{row('Fill at next hour close',w['stress_next_hour_fill'])}
{row('Fill at next hour +1c, volume>0 required',w['stress_worst_fill'])}
{row('Placebo: blend shuffled across days (coef '+str(w['placebo_shuffled_forecast']['mean_lpm_coef'])+')',w['placebo_shuffled_forecast'])}

Brier: market {w['brier_market']}, blend {w['brier_blend']}, combined {w['brier_combined']}; mean blend coefficient {w['mean_lpm_coef']}. Blend diagnostics (OLS): {W['modes']['ols']['blend_diag_summary']['rank_deficient_fits']} of {W['modes']['ols']['blend_diag_summary']['n_fits']} station-year fits have condition number > 1e8 (median {W['modes']['ols']['blend_diag_summary']['median_cond']:.0f}); ridge OOS MAE by year {W['modes']['ridge']['blend_diag_summary']['oos_mae_by_year']} vs OLS {W['modes']['ols']['blend_diag_summary']['oos_mae_by_year']}.
Mean pairwise correlation of daily station P&L: {w['mean_pairwise_daily_corr_between_stations']}; share of events with more than one position: {w['events_with_multiple_positions_share']}.

Specification curve (h8, OLS): """+'; '.join(f"thr {k.split('_')[0][3:]} slip {k.split('_')[1][4:]}: {c(v['pnl_ct'])} (t_event {v['t_event']}, N {v['N']:,})" for k,v in w['spec_curve'].items())+f"""

By station (per contract, event-clustered t): """+'; '.join(f"{k} {c(v['pnl_ct'])} (t {v['t_event']}, n {v['n']})" for k,v in sorted(w['by_station'].items(),key=lambda kv:-kv[1]['pnl_ct']))+f"""

Leave-one-station-out event-clustered t: min {min(w['loco'].values())}, max {max(w['loco'].values())}.

Capacity (10% participation, cap 100 contracts/signal): trailing-6h volume sizing (known at decision time) {w['capacity']['trailing_volume_part0.1']}; the earlier future-volume sizing {w['capacity']['future_volume_INFEASIBLE_part0.1']} is INFEASIBLE as a one-shot order and is shown only for comparison. Both are volume proxies, not depth.

Other snapshots (OLS, primary spec): D 00Z {c(W['modes']['ols']['h10']['primary']['pnl_ct'])} (t_event {W['modes']['ols']['h10']['primary']['t_event']}, N {W['modes']['ols']['h10']['primary']['N']:,}); D 02Z {c(W['modes']['ols']['h12']['primary']['pnl_ct'])} (t_event {W['modes']['ols']['h12']['primary']['t_event']}, N {W['modes']['ols']['h12']['primary']['N']:,}).

Universe reconciliation: {W['reconciliation']}

## Strategy 2: cross-venue, Kalshi-implied probability -> Polymarket brackets (threshold 5c, 2c half-spread)
{Xv['spec']['holdout_label']}. Cities {Xv['spec']['cities']}. Reconciliation: {Xv['reconciliation']}.

{hdr}
{row('Development (target <= 2026-03-31), adaptive monthly refit',xd)}
{row('Holdout (2026-04-01 .. 2026-09), adaptive monthly refit (fixed specification)',xh)}
{row('Holdout, coefficients FROZEN at 2026-03-31',xf)}
{row('Holdout, with the NWP blend as third input',xb)}
{row('All',x1)}
{row('All, equal weight per bracket (GLM)',Xv['trading']['lp+lx|ALL|equal_weight_per_bracket_GLM'])}
"""+(row('All, Polymarket quote age <= 15 min only',Xv['trading']['lp+lx|ALL|poly_price_age_le_15min'])+'\n' if 'lp+lx|ALL|poly_price_age_le_15min' in Xv['trading'] else '')+f"""
Information (event-clustered logit on the Polymarket panel): ALL {Xv['information']['ALL']['lp+lx']}; with blend {Xv['information']['ALL']['lp+lx+lpm']}; HOLDOUT {Xv['information']['HOLDOUT']['lp+lx']}."""+(f" Quote age <= 15 min: {Xv['information'].get('ALL_poly_price_age_le_15min')}; quote age > 60 min: {Xv['information'].get('ALL_poly_price_age_gt_60min')}. Quote-age quantiles (min): {Xv.get('price_age_minutes_quantiles')}." if 'ALL_poly_price_age_le_15min' in Xv['information'] else '')+f"""

Identical contracts (same station, same 2F bins; Miami, Atlanta, Seattle): {ic['rows']:,} bracket-hours, {ic['events']} events. Settlement disagreement between venues: {ic['settlement_disagreement_share_brackets']*100:.1f}% of brackets ({ic['settlement_disagreement_by_city']}), {ic['events_with_any_disagreement']*100:.1f}% of events -> the pairs are not economically identical; the price-discovery statistics below are therefore "cross-venue predictive information", not a pure common-efficient-price decomposition.
VECM information share (library implementation): {vi}
Pooled error correction: {Xv['pooled_error_correction']}
Model-free identical-contract trade (|Kalshi mid - Poly mid| > 8c): DEV {c(Xv['model_free_identical|DEV']['pnl_ct'])} (t_event {Xv['model_free_identical|DEV']['t_event']}, N {Xv['model_free_identical|DEV']['N']}); HOLDOUT {c(Xv['model_free_identical|HOLDOUT']['pnl_ct'])} (t_event {Xv['model_free_identical|HOLDOUT']['t_event']}, N {Xv['model_free_identical|HOLDOUT']['N']}); scored on Kalshi's settlement instead: DEV {c(Xv['model_free_identical|DEV|scored_on_kalshi_settlement'])}, HOLDOUT {c(Xv['model_free_identical|HOLDOUT|scored_on_kalshi_settlement'])}.
Alternative strip mapping (piecewise-linear CDF instead of a fitted normal): {Xv.get('alt_strip_mapping_piecewise_linear',{})}
Markouts after entry (signed Polymarket price move in the trade's favour, before spread): {Xv['markouts']}
Breakdowns: by city {Xv['breakdowns']['by_city']}; holdout by city {Xv['breakdowns']['by_city_holdout']}; by season {Xv['breakdowns']['by_season']}; by Kalshi hours since open {Xv['breakdowns']['by_kalshi_hours_since_open']}; leave-one-city-out t_event {Xv['breakdowns']['loco_t_event']}; leave-one-city-out holdout per contract {Xv['breakdowns']['loco_holdout_pnl_ct']}.
Specification curve: """+'; '.join(f"{k}: {c(v['pnl_ct'])} (t {v['t_event']}, N {v['N']})" for k,v in Xv['spec_curve'].items() if k.endswith('_HOLDOUT'))+f"""

Capacity: no historical Polymarket depth exists in this dataset; no dollar capacity figure is claimed. Live books observed on 2026-09-27 showed 1-3c spreads and hundreds to ~2,000 contracts within 2c of the touch on NYC/Miami brackets.

## Open blockers (cannot be closed with data on disk)
1. Winter forecast publication timestamps (strategy 1, P0): needs a run-level archive (NOAA AWS GFS/HRRR/NBM) for Nov 2025-Mar 2026.
2. Historical executable order books for both venues (P1): fills are modelled from quotes; forward capture is the remedy.
3. Backtest/live feature parity for the paper runner (P1): run initialization times are not recorded by live_signal.py.
4. External timestamp for the holdout chronology: the repository was placed under git on {man['built_utc'][:10]}; earlier chronology is self-reported.
"""
(OUT/'RESULTS.md').write_text(md); print('RESULTS.md written')
print('release built:', OUT)
